public abstract class AggregateRoot
{
    private readonly List<DomainEvent> _domainEvents = new();

    public IReadOnlyList<DomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    protected void RaiseDomainEvent(DomainEvent domainEvent)
        => _domainEvents.Add(domainEvent);

    public void ClearDomainEvents() => _domainEvents.Clear();
}

public class Order : AggregateRoot
{
    public OrderStatus Status { get; private set; }

    public void Place(CustomerId customerId, IReadOnlyList<OrderLine> lines)
    {
        // invariant checks ...
        Status = OrderStatus.Placed;
        RaiseDomainEvent(new OrderPlaced(Id, customerId, lines, DateTime.UtcNow));
    }
}

// Application service — post-commit publication
public async Task PlaceOrderAsync(PlaceOrderCommand cmd)
{
    var order = Order.Create(cmd.CustomerId, cmd.Lines);
    await _repository.SaveAsync(order);           // commit transaction
    foreach (var evt in order.DomainEvents)
        await _publisher.PublishAsync(evt);       // publish after commit
    order.ClearDomainEvents();
}
